package gateway;
network Main {
 submodules:
  src: gateway.Controller;
  gw: gateway.Fanout;
  sinkB: gateway.Controller;
  sinkC: gateway.Controller;
  busA: gateway.Bus;
  busB: gateway.Bus;
  busC: gateway.Bus;
 connections:
  src.tx --> gateway.Wire --> busA.rx_a;
  busA.tx_a --> gateway.Wire --> src.rx;
  gw.tx_a --> gateway.Wire --> busA.rx_b;
  busA.tx_b --> gateway.Wire --> gw.rx_a;
  gw.tx_b --> gateway.Wire --> busB.rx_a;
  busB.tx_a --> gateway.Wire --> gw.rx_b;
  sinkB.tx --> gateway.Wire --> busB.rx_b;
  busB.tx_b --> gateway.Wire --> sinkB.rx;
  gw.tx_c --> gateway.Wire --> busC.rx_a;
  busC.tx_a --> gateway.Wire --> gw.rx_c;
  sinkC.tx --> gateway.Wire --> busC.rx_b;
  busC.tx_b --> gateway.Wire --> sinkC.rx;
}

package gateway;
simple Controller {
 parameters:
  @class("dir.can.MultibusController");
  int queueCapacity = default(64);
  double txProcessingDelay @unit(s) = default(0ps);
  double rxProcessingDelay @unit(s) = default(0ps);
  string rxFilter = default("*");
 gates: output tx; input rx;
}
simple Bus {
 parameters:
  @class("dir.can.MultibusBus");
  double bitrate @unit(bps) = default(500kbps);
  string profile = default("can.cc.multibus.v1");
 gates: input rx_a; output tx_a; input rx_b; output tx_b;
}
channel Wire {
 parameters:
  @class("dir.link.FixedDelay");
  double delay @unit(s) = default(0ps);
}
module Gateway {
 gates:
  input rx_a; output tx_a;
  input rx_b; output tx_b;
 submodules:
  a: gateway.Controller;
  b: gateway.Controller;
 connections:
  rx_a --> a.rx;
  a.tx --> tx_a;
  rx_b --> b.rx;
  b.tx --> tx_b;
}
module Fanout {
 gates:
  input rx_a; output tx_a;
  input rx_b; output tx_b;
  input rx_c; output tx_c;
 submodules:
  a: gateway.Controller;
  b: gateway.Controller;
  c: gateway.Controller;
 connections:
  rx_a --> a.rx;
  a.tx --> tx_a;
  rx_b --> b.rx;
  b.tx --> tx_b;
  rx_c --> c.rx;
  c.tx --> tx_c;
}
